import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Radar,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
} from 'recharts';
import { HeartPulse, Award } from 'lucide-react';
import EmptyState from './EmptyState.jsx';

export const HealthAnalytics = ({ data }) => {
  if (!data || !data.score_trend || data.score_trend.length === 0) {
    return <EmptyState title="No Financial Health History" message="Calculate your financial health score to view historical trend reports." />;
  }

  const { latest_score, latest_grade, score_trend } = data;

  const radarData = [
    { subject: 'Savings', A: score_trend[score_trend.length - 1]?.savings_score || 80, fullMark: 100 },
    { subject: 'Budgeting', A: score_trend[score_trend.length - 1]?.budget_score || 85, fullMark: 100 },
    { subject: 'Emergency', A: 75, fullMark: 100 },
    { subject: 'Debt Ratio', A: 90, fullMark: 100 },
    { subject: 'Investment', A: 70, fullMark: 100 },
  ];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="p-6 rounded-3xl bg-gradient-to-br from-emerald-500/20 to-teal-500/10 border border-emerald-500/30 text-emerald-400">
          <div className="flex items-center gap-2">
            <HeartPulse className="w-5 h-5" />
            <span className="text-xs font-extrabold uppercase tracking-wider text-slate-400">Latest Health Score</span>
          </div>
          <h3 className="text-4xl font-black text-white mt-2">{latest_score} <span className="text-lg text-slate-400 font-normal">/ 100</span></h3>
        </div>

        <div className="p-6 rounded-3xl bg-gradient-to-br from-indigo-500/20 to-purple-500/10 border border-indigo-500/30 text-indigo-400">
          <div className="flex items-center gap-2">
            <Award className="w-5 h-5" />
            <span className="text-xs font-extrabold uppercase tracking-wider text-slate-400">Financial Health Grade</span>
          </div>
          <h3 className="text-4xl font-black text-white mt-2">Grade {latest_grade}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Line Chart */}
        <div className="bg-bg-surface/80 backdrop-blur-xl border border-border-subtle p-6 rounded-3xl shadow-xl space-y-4">
          <h3 className="text-sm font-bold text-white uppercase tracking-wider">
            Health Score Historical Trend
          </h3>
          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={score_trend}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.3} />
                <XAxis dataKey="date" stroke="#94A3B8" fontSize={10} />
                <YAxis domain={[0, 100]} stroke="#94A3B8" fontSize={10} />
                <Tooltip contentStyle={{ backgroundColor: '#0F172A', borderColor: '#334155', borderRadius: '16px', color: '#fff' }} />
                <Line type="monotone" dataKey="score" stroke="#10B981" strokeWidth={3} dot={{ r: 4, fill: '#10B981' }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Radar Chart */}
        <div className="bg-bg-surface/80 backdrop-blur-xl border border-border-subtle p-6 rounded-3xl shadow-xl space-y-4">
          <h3 className="text-sm font-bold text-white uppercase tracking-wider">
            Health Component Radar Analysis
          </h3>
          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}>
                <PolarGrid stroke="#334155" />
                <PolarAngleAxis dataKey="subject" stroke="#94A3B8" fontSize={10} />
                <PolarRadiusAxis angle={30} domain={[0, 100]} stroke="#94A3B8" fontSize={10} />
                <Radar name="Score" dataKey="A" stroke="#6366F1" fill="#6366F1" fillOpacity={0.5} />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HealthAnalytics;
