import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { Sparkles, TrendingUp } from 'lucide-react';
import EmptyState from './EmptyState.jsx';

const formatINR = (val) => `₹${Number(val || 0).toLocaleString('en-IN')}`;

export const ForecastAnalytics = ({ data }) => {
  if (!data || !data.forecast_history || data.forecast_history.length === 0) {
    return <EmptyState title="No Machine Learning Forecast History" message="Run Prophet AI cash flow forecasts to view historical trend reports." />;
  }

  const { forecast_records_count, forecast_history } = data;

  return (
    <div className="space-y-6">
      <div className="p-6 rounded-3xl bg-gradient-to-br from-primary-500/20 to-indigo-600/10 border border-primary-500/30 text-primary-300">
        <div className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-primary-400" />
          <span className="text-xs font-extrabold uppercase tracking-wider text-slate-400">ML Forecast Engine</span>
        </div>
        <h3 className="text-2xl font-black text-white mt-2">{forecast_records_count} Predictive Forecast Runs Logged</h3>
      </div>

      <div className="bg-bg-surface/80 backdrop-blur-xl border border-border-subtle p-6 rounded-3xl shadow-xl space-y-4">
        <h3 className="text-sm font-bold text-white uppercase tracking-wider">
          Prophet ML Projected Expense Amount Trend
        </h3>
        <div className="h-72 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={forecast_history}>
              <CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.3} />
              <XAxis dataKey="date" stroke="#94A3B8" fontSize={10} />
              <YAxis stroke="#94A3B8" fontSize={10} tickFormatter={(v) => `₹${v}`} />
              <Tooltip
                formatter={(val) => [formatINR(val), 'Projected Amount']}
                contentStyle={{ backgroundColor: '#0F172A', borderColor: '#334155', borderRadius: '16px', color: '#fff' }}
              />
              <Line type="monotone" dataKey="projected_amount" stroke="#8B5CF6" strokeWidth={3} dot={{ r: 4, fill: '#8B5CF6' }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default ForecastAnalytics;
