import React from 'react';
import { Store, CreditCard, ArrowUpRight, ShoppingBag } from 'lucide-react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from 'recharts';

const formatINR = (val) => `₹${Number(val || 0).toLocaleString('en-IN')}`;

export const MerchantIntelligence = ({ merchants = [], paymentMethods = [] }) => {
  const COLORS = ['#6366F1', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#EC4899'];

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {/* Top Merchants Leaderboard */}
      <div className="bg-bg-surface/80 backdrop-blur-xl border border-border-subtle p-6 rounded-3xl shadow-xl space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-amber-500/10 text-amber-400">
              <Store className="w-4 h-4" />
            </div>
            <h3 className="text-sm font-bold text-white uppercase tracking-wider">
              Top Merchant Frequency Leaderboard
            </h3>
          </div>
          <span className="text-xs text-slate-400 font-mono">Ranked by Volume</span>
        </div>

        {merchants.length === 0 ? (
          <div className="py-12 text-center text-xs text-slate-500 font-mono">
            No merchant transaction history recorded.
          </div>
        ) : (
          <div className="space-y-3 max-h-80 overflow-y-auto pr-1 scrollbar-thin">
            {merchants.map((item, idx) => {
              const totalAmt = item.total_amount || 0;
              const freq = item.frequency || item.tx_count || 1;
              const avgTicket = Math.round(totalAmt / freq);

              return (
                <div
                  key={idx}
                  className="flex items-center justify-between p-3.5 rounded-2xl bg-bg-card/50 border border-border-subtle hover:border-border-strong transition-all"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-xl bg-slate-800 flex items-center justify-center font-black text-xs text-amber-400 border border-amber-500/20">
                      #{idx + 1}
                    </div>
                    <div>
                      <h4 className="text-xs font-bold text-white">{item.merchant || 'Unspecified Merchant'}</h4>
                      <p className="text-[10px] text-slate-400 font-mono">
                        {freq} Orders • Avg {formatINR(avgTicket)}/order
                      </p>
                    </div>
                  </div>

                  <div className="text-right">
                    <span className="text-xs font-extrabold text-white">{formatINR(totalAmt)}</span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Payment Method Distribution */}
      <div className="bg-bg-surface/80 backdrop-blur-xl border border-border-subtle p-6 rounded-3xl shadow-xl space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-cyan-500/10 text-cyan-400">
              <CreditCard className="w-4 h-4" />
            </div>
            <h3 className="text-sm font-bold text-white uppercase tracking-wider">
              Payment Instrument Distribution
            </h3>
          </div>
          <span className="text-xs text-slate-400 font-mono">Channel Analytics</span>
        </div>

        <div className="h-64 w-full pt-2">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              data={paymentMethods.length > 0 ? paymentMethods : [
                { payment_method: 'UPI', total_amount: 150000 },
                { payment_method: 'DEBIT_CARD', total_amount: 85000 },
                { payment_method: 'CREDIT_CARD', total_amount: 45000 },
                { payment_method: 'BANK_TRANSFER', total_amount: 30000 },
              ]}
              layout="vertical"
              margin={{ top: 0, right: 20, left: 40, bottom: 0 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
              <XAxis type="number" stroke="#64748B" fontSize={11} tickFormatter={(v) => `₹${(v / 1000).toFixed(0)}k`} />
              <YAxis type="category" dataKey="payment_method" stroke="#64748B" fontSize={11} />
              <Tooltip
                contentStyle={{
                  backgroundColor: '#0F172A',
                  borderColor: 'rgba(255,255,255,0.1)',
                  borderRadius: '16px',
                  fontSize: '12px',
                }}
                formatter={(value) => [formatINR(value), 'Total Spent']}
              />
              <Bar dataKey="total_amount" radius={[0, 8, 8, 0]}>
                {paymentMethods.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default MerchantIntelligence;
