import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  FileText,
  PieChart,
  Scale,
  PiggyBank,
  Target,
  HeartPulse,
  Sparkles,
  ListFilter,
  Loader2,
  Calendar,
  DollarSign,
  TrendingUp,
} from 'lucide-react';

import { PageContainer } from '../../components/layout/PageContainer.jsx';
import ReportsHeader from '../../components/reports/ReportsHeader.jsx';
import ReportFilters from '../../components/reports/ReportFilters.jsx';
import AnalyticsCards from '../../components/reports/AnalyticsCards.jsx';
import MonthlyReportCard from '../../components/reports/MonthlyReportCard.jsx';
import CategoryAnalytics from '../../components/reports/CategoryAnalytics.jsx';
import IncomeExpenseAnalytics from '../../components/reports/IncomeExpenseAnalytics.jsx';
import SavingsAnalytics from '../../components/reports/SavingsAnalytics.jsx';
import BudgetAnalytics from '../../components/reports/BudgetAnalytics.jsx';
import GoalAnalytics from '../../components/reports/GoalAnalytics.jsx';
import HealthAnalytics from '../../components/reports/HealthAnalytics.jsx';
import ForecastAnalytics from '../../components/reports/ForecastAnalytics.jsx';
import TransactionSummary from '../../components/reports/TransactionSummary.jsx';
import ExecutiveRatios from '../../components/reports/ExecutiveRatios.jsx';
import ScenarioPlanner from '../../components/reports/ScenarioPlanner.jsx';
import MerchantIntelligence from '../../components/reports/MerchantIntelligence.jsx';

import reportService from '../../services/reportService.js';
import transactionService from '../../services/transactionService.js';

const TABS = [
  { id: 'overview', label: 'Executive Summary', icon: FileText },
  { id: 'category', label: 'Categories & Merchants', icon: PieChart },
  { id: 'income_expense', label: 'Income vs Expense', icon: Scale },
  { id: 'savings', label: 'Savings Accumulation', icon: PiggyBank },
  { id: 'budgets', label: 'Budget Performance', icon: DollarSign },
  { id: 'goals', label: 'Milestone Goals', icon: Target },
  { id: 'health', label: 'Health Score Trend', icon: HeartPulse },
  { id: 'forecast', label: 'Prophet AI Forecast', icon: Sparkles },
];

export const Reports = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [activeFilter, setActiveFilter] = useState('all');
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');
  const [summaryData, setSummaryData] = useState(() => {
    try {
      const cached = sessionStorage.getItem('reports_cache_summary');
      return cached ? JSON.parse(cached) : null;
    } catch {
      return null;
    }
  });

  const [loading, setLoading] = useState(() => {
    try {
      return !sessionStorage.getItem('reports_cache_summary');
    } catch {
      return true;
    }
  });

  const [monthlyReport, setMonthlyReport] = useState(null);
  const [categoryData, setCategoryData] = useState(null);
  const [incomeExpenseData, setIncomeExpenseData] = useState(null);
  const [savingsData, setSavingsData] = useState(null);
  const [budgetData, setBudgetData] = useState(null);
  const [goalData, setGoalData] = useState(null);
  const [healthData, setHealthData] = useState(null);
  const [forecastData, setForecastData] = useState(null);
  const [rawTransactions, setRawTransactions] = useState([]);

  const loadReportsData = async () => {
    if (!sessionStorage.getItem('reports_cache_summary')) setLoading(true);
    try {
      const [
        summaryRes,
        monthlyRes,
        categoryRes,
        incExpRes,
        savingsRes,
        budgetRes,
        goalRes,
        healthRes,
        forecastRes,
        txsRes,
      ] = await Promise.allSettled([
        reportService.getDashboardSummary(activeFilter, customStart, customEnd),
        reportService.getMonthlyReport(),
        reportService.getCategoryAnalysis(activeFilter, customStart, customEnd),
        reportService.getIncomeExpenseReport(activeFilter, customStart, customEnd),
        reportService.getSavingsAnalysis(),
        reportService.getBudgetAnalysis(),
        reportService.getGoalAnalysis(),
        reportService.getFinancialHealthReport(),
        reportService.getForecastSummaryReport(),
        transactionService.getTransactions({ page: 1, limit: 100 }),
      ]);

      if (summaryRes.status === 'fulfilled') {
        setSummaryData(summaryRes.value.data);
        if (activeFilter === 'all') {
          sessionStorage.setItem('reports_cache_summary', JSON.stringify(summaryRes.value.data));
        }
      }
      if (monthlyRes.status === 'fulfilled') setMonthlyReport(monthlyRes.value.data);
      if (categoryRes.status === 'fulfilled') setCategoryData(categoryRes.value.data);
      if (incExpRes.status === 'fulfilled') setIncomeExpenseData(incExpRes.value.data);
      if (savingsRes.status === 'fulfilled') setSavingsData(savingsRes.value.data);
      if (budgetRes.status === 'fulfilled') setBudgetData(budgetRes.value.data);
      if (goalRes.status === 'fulfilled') setGoalData(goalRes.value.data);
      if (healthRes.status === 'fulfilled') setHealthData(healthRes.value.data);
      if (forecastRes.status === 'fulfilled') setForecastData(forecastRes.value.data);
      if (txsRes.status === 'fulfilled') setRawTransactions(txsRes.value.data?.items || []);
    } catch (err) {
      console.error('Failed to load reports data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadReportsData();
  }, [activeFilter, customStart, customEnd]);

  const handleExport = async (format) => {
    await reportService.downloadReportFile(
      format,
      activeTab,
      activeFilter,
      customStart,
      customEnd
    );
  };

  // Dynamic fallbacks from rawTransactions if API arrays are empty
  const derivedCategories = useMemo(() => {
    if (categoryData?.categories?.length) return categoryData.categories;
    if (summaryData?.categories?.length) return summaryData.categories;
    if (!rawTransactions || !rawTransactions.length) return [];

    const catMap = {};
    rawTransactions.forEach((t) => {
      const type = (t.transaction_type || '').toUpperCase();
      if (type === 'EXPENSE') {
        const name = t.category?.category_name || t.category_name || 'General Expense';
        const color = t.category?.color || '#6366F1';
        const icon = t.category?.icon || 'Tag';
        const amt = Number(t.amount || 0);
        if (!catMap[name]) {
          catMap[name] = { category_name: name, color, icon, total_amount: 0, tx_count: 0 };
        }
        catMap[name].total_amount += amt;
        catMap[name].tx_count += 1;
      }
    });
    const list = Object.values(catMap);
    const total = list.reduce((sum, c) => sum + c.total_amount, 0);
    return list.map((c) => ({
      ...c,
      percentage: total > 0 ? Number(((c.total_amount / total) * 100).toFixed(2)) : 0,
    }));
  }, [categoryData, summaryData, rawTransactions]);

  const derivedMerchants = useMemo(() => {
    if (categoryData?.merchants?.length) return categoryData.merchants;
    if (summaryData?.merchants?.length) return summaryData.merchants;
    if (!rawTransactions || !rawTransactions.length) return [];

    const merchMap = {};
    rawTransactions.forEach((t) => {
      const mName = t.merchant || 'Unspecified Merchant';
      const amt = Number(t.amount || 0);
      if (!merchMap[mName]) merchMap[mName] = { merchant: mName, total_amount: 0, frequency: 0 };
      merchMap[mName].total_amount += amt;
      merchMap[mName].frequency += 1;
    });
    return Object.values(merchMap).sort((a, b) => b.total_amount - a.total_amount).slice(0, 10);
  }, [categoryData, summaryData, rawTransactions]);

  const derivedTrend = useMemo(() => {
    if (incomeExpenseData?.trend?.length) return incomeExpenseData.trend;
    if (monthlyReport?.monthly_breakdown?.length) return monthlyReport.monthly_breakdown;
    if (!rawTransactions || !rawTransactions.length) return [];

    const monthsMap = {};
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    rawTransactions.forEach((t) => {
      const d = new Date(t.transaction_date);
      const mIdx = isNaN(d.getTime()) ? 0 : d.getMonth();
      const mName = monthNames[mIdx];
      if (!monthsMap[mIdx]) {
        monthsMap[mIdx] = { month: mName, month_num: mIdx + 1, income: 0, expense: 0, savings: 0, savings_rate: 0 };
      }
      const amt = Number(t.amount || 0);
      const type = (t.transaction_type || '').toUpperCase();
      if (type === 'INCOME') {
        monthsMap[mIdx].income += amt;
      } else {
        monthsMap[mIdx].expense += amt;
      }
    });
    return Object.values(monthsMap)
      .sort((a, b) => a.month_num - b.month_num)
      .map((m) => {
        const sav = m.income - m.expense;
        const rate = m.income > 0 ? Number(((sav / m.income) * 100).toFixed(2)) : 0;
        return { ...m, savings: sav, savings_rate: rate };
      });
  }, [incomeExpenseData, monthlyReport, rawTransactions]);

  return (
    <PageContainer
      title="Financial Reports & Executive Analytics"
      description="Comprehensive PostgreSQL-driven analytics dashboard with dynamic calculations, interactive charts, and PDF/Excel/CSV exports."
    >
      <div className="space-y-6 max-w-7xl mx-auto">
        {/* Reports Header */}
        <ReportsHeader
          onRefresh={loadReportsData}
          isRefreshing={loading}
          onExport={handleExport}
          activeFilter={activeFilter}
        />

        {/* Date Filter Selector */}
        <ReportFilters
          activeFilter={activeFilter}
          onFilterChange={(f) => setActiveFilter(f)}
          customStart={customStart}
          customEnd={customEnd}
          onCustomRangeChange={(s, e) => {
            setCustomStart(s);
            setCustomEnd(e);
          }}
        />

        {/* Tab Selector with Hidden Scrollbar */}
        <div className="flex items-center space-x-2 border-b border-border-subtle overflow-x-auto pb-1 scrollbar-none [::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center space-x-2 px-4 py-3 text-xs font-bold transition-all border-b-2 whitespace-nowrap ${
                  isActive
                    ? 'border-primary-500 text-primary-400 bg-primary-500/10 rounded-t-2xl shadow-sm'
                    : 'border-transparent text-slate-400 hover:text-slate-200'
                }`}
              >
                <Icon className="w-4 h-4" />
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>

        {/* Loading Spinner */}
        {loading ? (
          <div className="py-24 flex flex-col items-center justify-center space-y-4">
            <Loader2 className="w-10 h-10 animate-spin text-primary-400" />
            <p className="text-xs text-slate-400 font-mono uppercase tracking-widest">
              Calculating PostgreSQL Report Metrics...
            </p>
          </div>
        ) : (
          <AnimatePresence mode="wait">
            <motion.div
              key={activeTab}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              className="space-y-6"
            >
              {activeTab === 'overview' && (
                <>
                  <AnalyticsCards kpis={summaryData?.kpis} />
                  <ExecutiveRatios kpis={summaryData?.kpis} />
                  <MonthlyReportCard monthlyData={monthlyReport} />
                  <ScenarioPlanner
                    currentMonthlySavings={summaryData?.kpis?.net_savings || 0}
                    currentMonthlyExpenses={summaryData?.kpis?.total_expenses || 0}
                  />
                  <TransactionSummary transactions={rawTransactions} />
                </>
              )}

              {activeTab === 'category' && (
                <>
                  <CategoryAnalytics
                    categories={derivedCategories}
                    merchants={derivedMerchants}
                  />
                  <MerchantIntelligence
                    merchants={derivedMerchants}
                    paymentMethods={summaryData?.payment_methods || []}
                  />
                </>
              )}

              {activeTab === 'income_expense' && (
                <>
                  <IncomeExpenseAnalytics
                    summary={incomeExpenseData?.summary || summaryData?.kpis}
                    trend={derivedTrend}
                  />
                  <ScenarioPlanner
                    currentMonthlySavings={summaryData?.kpis?.net_savings || 0}
                    currentMonthlyExpenses={summaryData?.kpis?.total_expenses || 0}
                  />
                </>
              )}

              {activeTab === 'savings' && (
                <SavingsAnalytics data={savingsData} />
              )}

              {activeTab === 'budgets' && (
                <BudgetAnalytics data={budgetData} />
              )}

              {activeTab === 'goals' && (
                <GoalAnalytics data={goalData} />
              )}

              {activeTab === 'health' && (
                <HealthAnalytics data={healthData || summaryData?.health_history} />
              )}

              {activeTab === 'forecast' && (
                <ForecastAnalytics data={forecastData} />
              )}
            </motion.div>
          </AnimatePresence>
        )}
      </div>
    </PageContainer>
  );
};

export default Reports;
