import React from 'react';
import {
  TrendingUp,
  TrendingDown,
  PiggyBank,
  Percent,
  Calendar,
  CreditCard,
  Store,
  Tag,
  Target,
  PieChart,
} from 'lucide-react';

const formatINR = (val) => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(val || 0);
};

export const AnalyticsCards = ({ kpis }) => {
  if (!kpis) return null;

  const cards = [
    {
      title: 'Total Income',
      value: formatINR(kpis.total_income),
      subText: `${kpis.transaction_count} Total Transactions`,
      icon: TrendingUp,
      color: 'from-emerald-500/20 to-teal-500/10 border-emerald-500/30 text-emerald-400',
    },
    {
      title: 'Total Expenses',
      value: formatINR(kpis.total_expenses),
      subText: `Highest: ${kpis.highest_expense_category}`,
      icon: TrendingDown,
      color: 'from-rose-500/20 to-pink-500/10 border-rose-500/30 text-rose-400',
    },
    {
      title: 'Net Savings',
      value: formatINR(kpis.net_savings),
      subText: `Savings Rate: ${kpis.savings_rate}%`,
      icon: PiggyBank,
      color: 'from-indigo-500/20 to-blue-500/10 border-indigo-500/30 text-indigo-400',
    },
    {
      title: 'Avg Daily Spend',
      value: formatINR(kpis.avg_daily_spending),
      subText: `Avg Monthly: ${formatINR(kpis.avg_monthly_spending)}`,
      icon: Calendar,
      color: 'from-amber-500/20 to-orange-500/10 border-amber-500/30 text-amber-400',
    },
    {
      title: 'Top Payment Method',
      value: kpis.most_used_payment_method,
      subText: `Top Merchant: ${kpis.most_frequent_merchant}`,
      icon: CreditCard,
      color: 'from-cyan-500/20 to-sky-500/10 border-cyan-500/30 text-cyan-400',
    },
    {
      title: 'Budget Utilization',
      value: `${kpis.budget_utilization_pct}%`,
      subText: `Goal Progress: ${kpis.goal_completion_pct}%`,
      icon: PieChart,
      color: 'from-purple-500/20 to-violet-500/10 border-purple-500/30 text-purple-400',
    },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {cards.map((card, idx) => {
        const Icon = card.icon;
        return (
          <div
            key={idx}
            className={`p-5 rounded-3xl bg-gradient-to-br border backdrop-blur-xl shadow-lg relative overflow-hidden transition-all duration-300 hover:scale-[1.02] ${card.color}`}
          >
            <div className="flex items-center justify-between">
              <span className="text-xs font-extrabold uppercase tracking-wider text-slate-400">
                {card.title}
              </span>
              <div className="p-2.5 rounded-2xl bg-bg-card/50 border border-white/10 shadow-sm">
                <Icon className="w-4 h-4" />
              </div>
            </div>

            <div className="mt-3">
              <h3 className="text-2xl font-black text-white tracking-tight">{card.value}</h3>
              <p className="text-[11px] text-slate-400 mt-1 font-mono">{card.subText}</p>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default AnalyticsCards;
